/* CentralHome.css */

/* Definición de Fuentes y Colores en :root */

.central-App {
  display: flex; /* Usamos Flexbox */
  flex-direction: column; /* Alinea los elementos en columna */
  justify-content: center; /* Centra los elementos verticalmente */
  align-items: center; /* Centra los elementos horizontalmente */
  min-height: 100vh; /* Asegura que la altura mínima ocupe toda la pantalla */
  text-align: center; /* Alinea el texto al centro */
  background: url("./assets/fondo.jpg");
  background-size: 100%, 100%;
  background-repeat: no-repeat;
  text-align: center;
  z-index: 10;
  height: 320vh;
}
/* configuracion estilos */

/* Estilos para las etiquetas de texto */

/* Títulos principales - h1 */

/* Fondo oscuro con gradiente acorde a la app */
.background {
}

h1 {
  font-family: var(--font-1-heading); /* Poppins para encabezados */
  font-size: 58px;
  color: var(--color-primary); /* Rojo oscuro */
  font-weight: bold;
  text-transform: uppercase;
  letter-spacing: 3px;
  margin-bottom: 20px;
}

/* Subtítulos - h2 */
h2 {
  font-family: var(--font-1-heading); /* Poppins */
  font-size: 26px;
  color: #ff6f00; /* Dorado oscuro */
  font-weight: bold;
  margin-bottom: 20px;
  letter-spacing: 2px;
}

/* Subtítulos secundarios - h3 */
h3 {
  font-family: var(--font-1-heading); /* Poppins */
  font-size: 28px;
  color: var(--color-light); /* Blanco */
  font-weight: normal;
  margin-bottom: 15px;
  letter-spacing: 1px;
}
.alca {
  color: #c4c8ce;
}
.container-comments-impresion {
  display: grid;
  grid-template-columns: repeat(3, 1fr); /* 3 columnas de igual tamaño */
  gap: 20px; /* Espacio entre los elementos */
  background-color: rgba(0, 0, 0, 0.8); /* Fondo oscuro con transparencia */
  padding: 40px; /* Espacio interno alrededor */
  height: 100vh; /* Altura definida para ocupar todo el alto de la pantalla */
  box-sizing: border-box; /* Incluye el padding dentro del tamaño total */
  overflow-y: auto; /* Asegura que haya scroll si hay muchos comentarios */
}

/* Estilo para cada comentario */
.comment-item {
  background-color: rgba(0, 0, 0, 0.9); /* Fondo más oscuro para los comentarios */
  border: 2px solid red; /* Bordes rojos para el contraste */
  border-radius: 12px; /* Bordes redondeados para suavizar la apariencia */
  padding: 20px;
  color: white; /* Letras blancas */
  display: flex;
  flex-direction: column;
  justify-content: flex-start; /* Alineación flexible */
  align-items: center;
  box-shadow: 0 4px 8px rgba(255, 0, 0, 0.3); /* Sombra sutil para destacar */
  transition: transform 0.3s ease-in-out, box-shadow 0.3s ease-in-out; /* Transiciones suaves */
}

.comment-item:hover {
  transform: scale(1.05); /* Efecto de zoom suave al pasar el ratón */
  box-shadow: 0 8px 16px rgba(255, 0, 0, 0.5); /* Sombra más prominente al hacer hover */
}

/* Estilo para el título de cada comentario */
.comment-title {
  font-size: 1.5rem; /* Título más grande para resaltar */
  margin: 0;
  font-weight: bold;
  text-align: center;
  color: #ffcc00; /* Color dorado para destacar el título */
}

/* Estilo para la fecha */
.comment-date {
  font-size: 1rem;
  color: #ddd; /* Gris claro para la fecha */
  margin-top: 12px;
  text-align: center;
  font-style: italic;
}

/* Estilos para el botón */
.button-first-style {
  background-color: #ff6f00; /* Naranja fluorescente */
  color: #ffffff; /* Blanco para el texto */
  border: 2px solid #ff6f00; /* Borde del mismo color que el fondo */
  padding: 15px 30px; /* Tamaño adecuado para el botón */
  font-size: 18px; /* Tamaño de la fuente */
  font-family: "Poppins", sans-serif; /* Fuente moderna */
  font-weight: bold;
  text-transform: uppercase; /* Mayúsculas para darle un estilo más moderno */
  border-radius: 50px; /* Bordes redondeados */
  transition: all 0.3s ease; /* Transición suave */
  cursor: pointer; /* Cambia el cursor cuando pasa por encima */
}

/* Estilo cuando se pasa el ratón por encima (hover) */
.button-first-style:hover {
  background-color: #007bff; /* Un naranja más fosforescente */
  color: white; /* Texto oscuro para contraste */
  box-shadow: 0 0 15px 5px blue; /* Efecto de brillo fosforescente */
  transform: scale(1.05); /* Efecto de agrandar ligeramente el botón */
  border: 2px solid blue; /* Borde que resalta también */
}

.container-central-btn {
  margin-top: 10px;
}

.youtube-container {
  margin-top: 100px;
}
.qr-img {
  width: 200px;
  height: 200px;
}
/* Párrafos - p */
p {
  font-family: var(--font-1-body); /* Roboto */
  font-size: 18px;
  color: #c4c8ce;
  line-height: 1.6; /* Mejor separación entre líneas */
  margin-bottom: 20px;
  text-align: justify;
}

/* Citas o textos destacados - blockquote */
blockquote {
  font-family: var(--font-2-body); /* Merriweather */
  font-size: 20px;
  color: var(--color-accent); /* Naranja */
  font-style: italic;
  border-left: 5px solid var(--color-primary); /* Rojo oscuro */
  padding-left: 15px;
  margin: 20px 0;
}

.container-initiated {
