  margin-top: -450px;
}

/* Texto pequeño */
small {
  font-size: 14px;
  color: var(--color-dark); /* Fondo oscuro */
}

/* Listas (sin numerar) */
ul {
  padding-left: 20px;
  margin-bottom: 20px;
}

ul li {
  font-family: var(--font-1-body); /* Roboto */
  font-size: 16px;
  color: var(--color-light); /* Blanco */
