:root {
  /* Fuentes */
  --font-1-body: "Roboto", sans-serif;
  --font-1-heading: "Poppins", sans-serif;
  --font-2-body: "Merriweather", serif;
  --font-2-heading: "Lora", serif;

  /* Colores */
  --color-primary: #ff6f00; /* Rojo oscuro */
  --color-secondary: #b8860b; /* Dorado oscuro */
  --color-light: #ffffff; /* Blanco */
  --color-dark: #111111; /* Fondo oscuro */
  --color-hover: #ff6f00; /* Azul al pasar el mouse */
  --color-accent: #ff7f50; /* Naranja */

  /* Fondos */
  --background-main: #111111; /* Fondo más oscuro */
